export const RESULTS_CSS = `:root{--c:#FEFBF6;--s:#F1ECE5;--b:#F9D2D2;--t:#82736C;--n:#3F3D3E;--f:#485B59;--r:#A40713;--w:#FFF;--bc:#CFC3C3}*,*:before,*:after{box-sizing:border-box}html,body{margin:0;padding:0;background:var(--s);min-height:100dvh;font-family:Montserrat,Helvetica,Arial,sans-serif;color:var(--n);-webkit-font-smoothing:antialiased}.pvb-results-page{display:flex;flex-direction:column;min-height:100dvh;max-width:440px;margin:0 auto;padding:28px 24px 0}.pvb-top-bar{display:flex;justify-content:center;align-items:center;margin-bottom:20px}.pvb-shop-name{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.045em;color:var(--t);margin:0}.pvb-hero{display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;margin-bottom:14px}.pvb-avatar{width:48px;height:48px;background:var(--b);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:700;color:var(--n)}.pvb-avatar svg{width:22px;height:22px}.pvb-headline{font-family:GT Ultra Fine,Georgia,serif;font-size:30px;line-height:34px;font-weight:400;margin:0}.pvb-subline{font-size:12px;color:#606060;margin:0}.pvb-tabs{display:flex;gap:6px;margin-bottom:14px;overflow-x:auto;-webkit-overflow-scrolling:touch}.pvb-tab{font-size:12px;font-weight:600;padding:6px 12px;border-radius:999px;background:var(--w);color:var(--n);border:none;cursor:pointer;white-space:nowrap;flex-shrink:0}.pvb-tab-active{background:var(--n);color:var(--c)}.pvb-section{margin-bottom:14px}.pvb-section-header{display:flex;justify-content:space-between;align-items:baseline;margin:4px 2px 8px}.pvb-section-title{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.045em;margin:0}.pvb-section-price{font-size:12px;color:var(--t)}.pvb-toggle{font-size:12px;color:var(--t);background:none;border:none;cursor:pointer;padding:0;text-decoration:underline}.pvb-items{display:flex;flex-direction:column;gap:8px}.pvb-item{display:flex;align-items:center;gap:12px;background:var(--w);border-radius:14px;padding:8px 12px 8px 8px}.pvb-item.pass-row{opacity:.6}.pvb-item.waiting{opacity:.55}.pvb-item-thumb{width:56px;height:56px;border-radius:10px;background:var(--c);padding:6px;flex-shrink:0}.pvb-item-thumb img{width:100%;height:100%;object-fit:contain;mix-blend-mode:multiply;display:block}.pvb-item-info{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}.pvb-item-title{font-size:13px;font-weight:600;line-height:17px;margin:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.pvb-item-meta{font-size:12px;color:var(--t);margin:0}.pvb-item-reason{font-size:11px;color:var(--t);margin:2px 0 0;font-style:italic}.pvb-tag{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.045em;padding:4px 9px;border-radius:999px;flex-shrink:0}.pvb-tag-love{background:var(--f);color:var(--w)}.pvb-tag-maybe{border:1px solid var(--t);color:var(--t);background:transparent}.pvb-tag-pass{border:1px solid var(--r);color:var(--r);background:transparent}.pvb-tag-sold{background:var(--s);color:var(--t)}.pvb-tag-wait{color:var(--t);background:transparent}.pvb-btn-ghost{height:34px;padding:0 14px;border-radius:999px;border:1px solid var(--n);background:transparent;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.045em;color:var(--n);cursor:pointer;flex-shrink:0}.pvb-btn-ghost:hover{background:var(--n);color:var(--c)}.pvb-btn-ghost.added{background:var(--f);color:var(--w);border-color:var(--f);pointer-events:none}.pvb-progress-bar{display:flex;gap:6px;padding:0 30px;margin:8px 0}.pvb-progress-seg{flex:1;height:4px;border-radius:999px;background:var(--bc)}.pvb-progress-seg.done{background:var(--n)}.pvb-so-far{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.045em;color:var(--t);margin:12px 0 6px}.pvb-sticky{position:fixed;bottom:0;left:0;right:0;background:var(--s);box-shadow:0 -10px 20px -14px #3f3d3e59;padding:14px 24px 30px;padding-bottom:max(30px,env(safe-area-inset-bottom));display:flex;flex-direction:column;gap:8px;align-items:center;z-index:50}.pvb-btn-primary{width:100%;max-width:340px;height:54px;border-radius:999px;background:var(--n);color:var(--c);font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:.045em;border:none;cursor:pointer;text-decoration:none;display:flex;align-items:center;justify-content:center}.pvb-btn-primary:disabled{opacity:.6;cursor:not-allowed}.pvb-sticky-note{font-size:12px;color:#606060;text-align:center;line-height:18px}.pvb-spacer{height:140px}.pvb-faces{display:flex;gap:18px;justify-content:center;margin-bottom:14px}.pvb-face{border:0;padding:0;background:none;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:6px;font-family:inherit;font-size:11px;font-weight:600;color:var(--n)}.pvb-face-av{width:48px;height:48px;border-radius:999px;overflow:hidden;position:relative;flex-shrink:0}.pvb-face-av svg{display:block;border-radius:999px}.pvb-face.wait .pvb-face-av{opacity:.4}.pvb-face-ok{position:absolute;right:-2px;bottom:-2px;width:18px;height:18px;border-radius:999px;background:var(--f);border:2px solid var(--c);display:flex;align-items:center;justify-content:center}.pvb-notice{background:var(--c);border-radius:12px;padding:14px 16px;font-size:13px;color:var(--t);margin-bottom:14px;text-align:center}.pvb-toast{position:fixed;bottom:160px;left:50%;transform:translate(-50%);background:var(--n);color:var(--c);padding:12px 20px;border-radius:999px;font-size:12px;font-weight:600;opacity:0;transition:opacity .3s;pointer-events:none;z-index:100}.pvb-toast.show{opacity:1}.pvb-hidden{display:none!important}
`;

